package com.backend.nutri_predic.plandia.entity; import com.backend.nutri_predic.cliente.entity.Cliente; import com.backend.nutri_predic.consumo.entity.EvaluacionConsumo; import jakarta.persistence.*;
@Entity @Table(name="intervenciones_consumo_diarias",uniqueConstraints=@UniqueConstraint(columnNames={"evaluacion_consumo_id","criterio_evaluado_id"})) public class IntervencionConsumoDiaria {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="cliente_id") private Cliente cliente; @ManyToOne(optional=false) @JoinColumn(name="evaluacion_consumo_id") private EvaluacionConsumo evaluacionConsumo; @ManyToOne @JoinColumn(name="plan_diario_id") private PlanDiario planDiario; private Long criterioEvaluadoId; @Column(length=100) private String componente; @Column(length=30) private String fuenteExceso; @Column(length=1000) private String referenciaUtilizada; @Column(length=1000) private String mensajeEstructurado; public Long getId(){return id;} public void setCliente(Cliente v){cliente=v;} public void setEvaluacionConsumo(EvaluacionConsumo v){evaluacionConsumo=v;} public void setPlanDiario(PlanDiario v){planDiario=v;} public void setCriterioEvaluadoId(Long v){criterioEvaluadoId=v;} public void setComponente(String v){componente=v;} public void setFuenteExceso(String v){fuenteExceso=v;} public void setReferenciaUtilizada(String v){referenciaUtilizada=v;} public void setMensajeEstructurado(String v){mensajeEstructurado=v;}}
